let __v_235 = pyrt::literals::decode("{\"$tuple\":[\"What a price covers is written where it is sold: the booking page lists what comes with it, and anything it does not list is charged on top, often at the desk rather than before. Ask for the total in writing before you pay, and keep that email for the day itself.\",\"Included and not included are two lists, and the second is the one that costs you: it is on the page you book on, then at the desk, where the extras get added. Read the first list before you book and ask for the total by email, because that is the version they have to honour.\",\"A room, a package or a rate names what comes with it in its own terms, and whatever it does not name is charged separately - parking, breakfast and the wifi are the usual three. Check that list before you book, and ring to confirm what applies to your own booking.\"]}")?;
